			return rangeInfo.isSameByte();
		}
	}

	private class BlockNameTableColumn : AbstractDynamicTableColumn<AddressRangeInfo, string, object> {

		/* @Override */
		public string getColumnName() {
			return "Block Name";
		}

		/* @Override */
		public string getValue(AddressRangeInfo rangeInfo, Settings settings, object data,
				ServiceProvider services)
    {
			return program.getMemory().getBlock(rangeInfo.min()).getName();
		}
	}

	private class NumRefsToTableColumn : AbstractDynamicTableColumn<AddressRangeInfo, Integer, object> {

		/* @Override */
		public string getColumnName() {
			return "To References";
		}

		/* @Override */
